# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞRUSAL FONKSİYONLARLA GERÇEK YAŞAM MODELLEMESİ (MAT.9.2.3)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">MODELLEME ADIMLARI VE BİLEŞENLER</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">Doğrusal Model: f(x) = a · x + b</text>\n  <text x="35" y="120" font-size="10.5" fill="#1d4ed8">• b (Sabit Terim / Başlangıç Değeri - f(0)):</text>\n  <text x="43" y="136" font-size="10" fill="#1e3a8a">Sabit ücret, taksimetre açılış ücreti, dikilen fidanın</text>\n  <text x="43" y="150" font-size="10" fill="#1e3a8a">ilk boyu, depodaki başlangıç su miktarı.</text>\n  <text x="35" y="174" font-size="10.5" fill="#1d4ed8">• a (Eğim / Birim Değişim Oranı - Δy / Δx):</text>\n  <text x="43" y="190" font-size="10" fill="#1e3a8a">Birim zamandaki artış (+a) veya azalış (-a) miktarı.</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#b91c1c">• Başabaş Noktası: f(x) = g(x) (İki doğrunun kesişimi)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">KARŞILAŞTIRMALI TARİFE ANALİZİ</text>\n  <line x1="395" y1="210" x2="650" y2="210" stroke="#334155" stroke-width="2"/>\n  <line x1="395" y1="210" x2="395" y2="85" stroke="#334155" stroke-width="2"/>\n  <line x1="395" y1="185" x2="635" y2="95" stroke="#2563eb" stroke-width="2.5"/>\n  <line x1="395" y1="150" x2="635" y2="120" stroke="#dc2626" stroke-width="2.5"/>\n  <circle cx="508" cy="142" r="5" fill="#15803d"/>\n  <line x1="508" y1="142" x2="508" y2="210" stroke="#15803d" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <text x="508" y="226" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">x = x0 (Eşitlik)</text>\n  <text x="605" y="92" font-size="10.5" font-weight="bold" fill="#2563eb">f(x) (A Firması)</text>\n  <text x="605" y="136" font-size="10.5" font-weight="bold" fill="#dc2626">g(x) (B Firması)</text>\n  <text x="410" y="102" font-size="10" fill="#14532d">• x &lt; x0 iken A ucuz;</text>\n  <text x="410" y="116" font-size="10" fill="#14532d">• x &gt; x0 iken B ucuzdur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MUTLAK DEĞERLİ DENKLEM VE EŞİTSİZLİK PROBLEMLERİ (TOLERANS ARALIĞI)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">İDEAL DEĞER VE SAPMA (HATA PAYI) MODELİ</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#78350f">• İdeal (Hedef) Değer = a  |  Sapma (Tolerans) = Δ</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#b91c1c">1) Sınır Değerler (En Az ve En Çok): |x - a| = Δ</text>\n  <text x="43" y="138" font-size="10.5" fill="#92400e">x_min = a - Δ   ve   x_max = a + Δ</text>\n  <text x="35" y="164" font-size="11" font-weight="bold" fill="#15803d">2) Kabul Edilebilir (Standart) Aralık: |x - a| ≤ Δ</text>\n  <text x="43" y="182" font-size="10.5" fill="#92400e">-Δ ≤ x - a ≤ Δ   ⇒   a - Δ ≤ x ≤ a + Δ</text>\n  <text x="35" y="208" font-size="11" font-weight="bold" fill="#1e40af">3) Standart Dışı (Hatalı) Bölge: |x - a| &gt; Δ</text>\n  <text x="43" y="226" font-size="10.5" fill="#92400e">x &lt; a - Δ   veya   x &gt; a + Δ</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">UÇ DEĞERLERDEN DENKLEM KURMA</text>\n  <text x="375" y="96" font-size="10.5" fill="#581c87">Bir niceliğin alabileceği en küçük değer x_min ve</text>\n  <text x="375" y="112" font-size="10.5" fill="#581c87">en büyük değer x_max verildiğinde:</text>\n  <text x="375" y="138" font-size="11" font-weight="bold" fill="#6b21a8">• Merkez (Ortalama): a = (x_min + x_max) / 2</text>\n  <text x="375" y="162" font-size="11" font-weight="bold" fill="#6b21a8">• Sapma (Yarıçap): Δ = (x_max - x_min) / 2</text>\n  <rect x="375" y="178" width="290" height="50" rx="8" fill="#ffffff" stroke="#d8b4fe" stroke-width="1.5"/>\n  <text x="385" y="198" font-size="10.5" font-weight="bold" fill="#581c87">Örnek: 18 °C ile 26 °C arası konfor sıcaklığı:</text>\n  <text x="385" y="216" font-size="10.5" font-weight="bold" fill="#b91c1c">a = (18+26)/2 = 22, Δ = (26-18)/2 = 4 ⇒ |x - 22| ≤ 4</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PARÇALI DOĞRUSAL TARİFELER (KADEMELİ FATURALANDIRMA)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">KADEMELİ SU / ELEKTRİK / KARGO MODELİ</text>\n  <text x="35" y="96" font-size="10.5" fill="#1e3a8a">Tüketim miktarına (x) göre birim fiyatın değiştiği</text>\n  <text x="35" y="112" font-size="10.5" fill="#1e3a8a">durumlar parçalı doğrusal fonksiyonla modellenir:</text>\n  <text x="35" y="138" font-size="10.5" font-weight="bold" fill="#1e40af">Örnek Su Tarifesi (x m³ tüketim):</text>\n  <text x="43" y="156" font-size="10.5" fill="#1d4ed8">• 1. Kademe (0 ≤ x ≤ 15 m³): m³ başına 20 TL</text>\n  <text x="52" y="172" font-size="10.5" font-weight="bold" fill="#1e3a8a">f(x) = 20x</text>\n  <text x="43" y="194" font-size="10.5" fill="#1d4ed8">• 2. Kademe (x &gt; 15 m³): Aşan her m³ için 30 TL</text>\n  <text x="52" y="212" font-size="10.5" font-weight="bold" fill="#b91c1c">f(x) = 20·15 + 30·(x - 15) = 30x - 150</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">STRATEJİ VE DOĞRULAMA (MAT.9.2.3.f-h)</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#881337">1. Temsiller Arası Dönüşüm:</text>\n  <text x="383" y="112" font-size="10" fill="#9f1239">Sözel problem → Tablo → Cebirsel denklem → Grafik.</text>\n  <text x="375" y="138" font-size="10.5" font-weight="bold" fill="#881337">2. Kök ve Tanım Kümesi Kontrolü:</text>\n  <text x="383" y="154" font-size="10" fill="#9f1239">Bulunan x değeri gerçek yaşam bağlamına uygun</text>\n  <text x="383" y="170" font-size="10" fill="#9f1239">olmalıdır (zaman, kütle, adet negatif olamaz!).</text>\n  <text x="375" y="196" font-size="10.5" font-weight="bold" fill="#15803d">3. Farklı Stratejilerin Karşılaştırılması:</text>\n  <text x="383" y="212" font-size="10" fill="#166534">Grafik kesişimi ile cebirsel çözüm aynı sonucu verir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
